typedef struct { const char *key; void *impl; } ext_t;
struct document { ext_t exts[4]; size_t n; };

void *get_extension(const struct document *d, const char *key) {
    for (size_t i = 0; i < d->n; i++)
        if (strcmp(d->exts[i].key, key) == 0) return d->exts[i].impl;
    return NULL;                      /* capability absent */
}
